{{
(() => {
  const dry = !!($json.summary && $json.summary.dryRun);
  const ids = Array.isArray($json.processedContactIds)
    ? $json.processedContactIds.map((v) => String(v || '').trim()).filter(Boolean)
    : [];
  if (dry || ids.length === 0) return 'SELECT 1;';
  const quoted = ids.map((id) => "'" + id.replace(/'/g, "''") + "'").join(',');
  return `UPDATE "Emerald_Release_Log"
SET status = 'backfill_checked'
WHERE status = 'queued'
  AND NULLIF(TRIM(ghl_contact_id), '') IN (${quoted});`;
})()
}}

